def main():
    for rel, old, new, label in PATCHES:
        path = ROOT / rel
        text = path.read_text(encoding="utf-8")

        if new in text:
            print(f"[SKIP] {label}: already applied")
            continue

        count = text.count(old)
        if count != 1:
            raise RuntimeError(
                f"{label}: expected exactly one anchor, "
                f"found {count} in {path}"
            )

        path.write_text(
            text.replace(old, new, 1),
            encoding="utf-8",
        )
        print(f"[OK] {label}")

    print()
    print("=" * 72)
    print("SSA-SBC-V1 INTEGRATION PATCH: APPLIED")
    print("=" * 72)
    print("Do NOT restart API yet.")
    print("Run compile + wiring tests first.")


if __name__ == "__main__":
    main()
